#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=BLOCK-BAD
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=BLOCK-BAD
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=2001:db8:bad::/48 --dest-ip-ranges=::/0 --layer4-configs=all --enable-logging --description=BLOCK-BAD-V6
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=2001:db8:bad::/48 --dest-ip-ranges=::/0 --layer4-configs=all --enable-logging --description=BLOCK-BAD-V6
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:80,tcp:443 --enable-logging --description=LAN-2-INTERNET
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:80,tcp:443 --enable-logging --description=LAN-2-INTERNET
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.20.0.16/28,10.20.0.32/27,10.20.0.64/26,10.20.0.128/25 --dest-ip-ranges=10.10.0.0/16 --layer4-configs=tcp:80,tcp:443,tcp:8080 --enable-logging --description=SERVER-SYNC
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.20.0.16/28,10.20.0.32/27,10.20.0.64/26,10.20.0.128/25 --dest-ip-ranges=10.10.0.0/16 --layer4-configs=tcp:80,tcp:443,tcp:8080 --enable-logging --description=SERVER-SYNC
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.20.0.16/28,10.20.0.32/27,10.20.0.64/26,10.20.0.128/25 --layer4-configs=tcp:80,tcp:443,tcp:8080 --enable-logging '--description=SERVER-SYNC (back)'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.20.0.16/28,10.20.0.32/27,10.20.0.64/26,10.20.0.128/25 --layer4-configs=tcp:80,tcp:443,tcp:8080 --enable-logging '--description=SERVER-SYNC (back)'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.20.0.25/32,10.20.0.80/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:53,udp:53 --disabled --enable-logging --description=DNS-OUT
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.20.0.25/32,10.20.0.80/32 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:53,udp:53 --disabled --enable-logging --description=DNS-OUT
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=icmp --enable-logging --description=PING-ALL
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=icmp --enable-logging --description=PING-ALL
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=::/0 --dest-ip-ranges=2001:db8:20::/64 --layer4-configs=tcp:80,tcp:443 --enable-logging --description=V6-WEB
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=::/0 --dest-ip-ranges=2001:db8:20::/64 --layer4-configs=tcp:80,tcp:443 --enable-logging --description=V6-WEB
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.20.0.16/28,10.20.0.32/27,10.20.0.64/26,10.20.0.128/25 --layer4-configs=all --enable-logging --description=DENY-LAN-DMZ
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.20.0.16/28,10.20.0.32/27,10.20.0.64/26,10.20.0.128/25 --layer4-configs=all --enable-logging --description=DENY-LAN-DMZ
run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.20.0.25/32 --layer4-configs=47 --enable-logging --description=GRE-LAB
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.20.0.25/32 --layer4-configs=47 --enable-logging --description=GRE-LAB
run compute network-firewall-policies rules create 1200 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=BLOCKALL
run compute network-firewall-policies rules create 1210 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging --description=BLOCKALL
run compute network-firewall-policies rules create 1220 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1230 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1240 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1250 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   ADMIN-SSH (port2): the source of the rule is in zone port2, and a rule of Google Cloud names no zone: give the networks behind port2 with --zone-network
#   ADMIN-SSH (port1): the source of the rule is in zone port1, and a rule of Google Cloud names no zone: give the networks behind port1 with --zone-network
#   WEB-IN: not converted: action Dst NAT: how the API spells its target list is not known, so the translation is not read
#   UPDATES: the destination 'Updates (IPv4)' holds members only its platform knows; a rule of Google Cloud names addresses
#   TO-LAB: not converted: action Cascade: the rules of the rule list it hands traffic to are not read, and they decide that traffic
#   ODD: schedule '{"type": "recurring", "name": "Work-Hours"}' is not converted; the rule would apply at all times

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
